/* Fancybox 3 compatible — data-fancybox / data-caption API
 * Features: grouped navigation, mouse-wheel zoom, pinch-to-zoom,
 * touch pan, mouse drag pan, keyboard nav, click-outside close.
 */
(function () {
  'use strict';

  var overlay, inner, imgEl, captionEl, loaderEl, prevBtn, nextBtn;
  var groups = {};
  var cur = { group: null, idx: 0 };
  var z = { scale: 1, tx: 0, ty: 0, dragging: false, lx: 0, ly: 0 };
  var pinch = { on: false, d0: 0, s0: 1, mx: 0, my: 0 };
  var pan1 = { on: false, sx: 0, sy: 0, stx: 0, sty: 0 };

  /* ── DOM ── */
  function buildDOM() {
    overlay = document.createElement('div');
    overlay.className = 'fancybox-container';
    overlay.setAttribute('role', 'dialog');
    overlay.setAttribute('aria-modal', 'true');
    overlay.setAttribute('aria-label', 'Image viewer');

    overlay.innerHTML =
      '<div class="fancybox-bg"></div>' +
      '<div class="fancybox-inner">' +
        '<div class="fancybox-loader"><div class="fancybox-loader-spin"></div></div>' +
        '<img class="fancybox-image" alt="" />' +
      '</div>' +
      '<div class="fancybox-caption"></div>' +
      '<button class="fancybox-button fancybox-button--close" aria-label="Close">' +
        '<svg viewBox="0 0 24 24"><path d="M19 6.41L17.59 5 12 10.59 6.41 5 5 6.41 10.59 12 5 17.59 6.41 19 12 13.41 17.59 19 19 17.59 13.41 12z"/></svg>' +
      '</button>' +
      '<button class="fancybox-button fancybox-button--arrow_left" aria-label="Previous">' +
        '<svg viewBox="0 0 24 24"><path d="M15.41 16.59L10.83 12l4.58-4.59L14 6l-6 6 6 6z"/></svg>' +
      '</button>' +
      '<button class="fancybox-button fancybox-button--arrow_right" aria-label="Next">' +
        '<svg viewBox="0 0 24 24"><path d="M8.59 16.59L13.17 12 8.59 7.41 10 6l6 6-6 6z"/></svg>' +
      '</button>';

    document.body.appendChild(overlay);

    inner     = overlay.querySelector('.fancybox-inner');
    imgEl     = overlay.querySelector('.fancybox-image');
    captionEl = overlay.querySelector('.fancybox-caption');
    loaderEl  = overlay.querySelector('.fancybox-loader');
    prevBtn   = overlay.querySelector('.fancybox-button--arrow_left');
    nextBtn   = overlay.querySelector('.fancybox-button--arrow_right');

    overlay.querySelector('.fancybox-button--close').addEventListener('click', close);
    overlay.querySelector('.fancybox-bg').addEventListener('click', close);
    prevBtn.addEventListener('click', function (e) { e.stopPropagation(); navigate(-1); });
    nextBtn.addEventListener('click', function (e) { e.stopPropagation(); navigate(1); });

    document.addEventListener('keydown', function (e) {
      if (!overlay.classList.contains('fancybox-is-open')) return;
      if (e.key === 'Escape')      close();
      if (e.key === 'ArrowLeft')   navigate(-1);
      if (e.key === 'ArrowRight')  navigate(1);
    });

    inner.addEventListener('wheel',      onWheel,      { passive: false });
    imgEl.addEventListener('mousedown',  onMouseDown);
    document.addEventListener('mousemove', onMouseMove);
    document.addEventListener('mouseup',   onMouseUp);
    inner.addEventListener('touchstart', onTouchStart, { passive: false });
    inner.addEventListener('touchmove',  onTouchMove,  { passive: false });
    inner.addEventListener('touchend',   onTouchEnd);
    imgEl.addEventListener('dragstart',  function (e) { e.preventDefault(); });
  }

  /* ── Groups ── */
  function collectGroups() {
    groups = {};
    document.querySelectorAll('a[data-fancybox]').forEach(function (a) {
      var g = a.getAttribute('data-fancybox');
      if (!groups[g]) groups[g] = [];
      groups[g].push({ src: a.getAttribute('href'), caption: a.getAttribute('data-caption') || '', el: a });
    });
  }

  /* ── Open / Close / Navigate ── */
  function open(gName, idx) {
    cur.group = gName; cur.idx = idx;
    resetZoom();
    overlay.classList.add('fancybox-is-open');
    document.body.classList.add('fancybox-active');
    loadImage(groups[gName][idx]);
    updateNav();
  }

  function close() {
    overlay.classList.remove('fancybox-is-open');
    document.body.classList.remove('fancybox-active');
    imgEl.src = '';
    imgEl.classList.remove('fancybox-image--loaded');
    resetZoom();
  }

  function navigate(dir) {
    var list = groups[cur.group];
    if (!list) return;
    var n = cur.idx + dir;
    if (n < 0 || n >= list.length) return;
    cur.idx = n;
    imgEl.classList.remove('fancybox-image--loaded');
    resetZoom();
    loadImage(list[n]);
    updateNav();
  }

  function loadImage(item) {
    loaderEl.style.display = 'flex';
    imgEl.classList.remove('fancybox-image--loaded');
    captionEl.textContent = item.caption;
    var tmp = new Image();
    tmp.onload = function () {
      imgEl.src = item.src; imgEl.alt = item.caption;
      loaderEl.style.display = 'none';
      imgEl.classList.add('fancybox-image--loaded');
    };
    tmp.onerror = function () {
      loaderEl.style.display = 'none';
      imgEl.src = item.src;
      imgEl.classList.add('fancybox-image--loaded');
    };
    tmp.src = item.src;
  }

  function updateNav() {
    var list = groups[cur.group] || [];
    var multi = list.length > 1;
    prevBtn.style.visibility = (multi && cur.idx > 0)               ? 'visible' : 'hidden';
    nextBtn.style.visibility = (multi && cur.idx < list.length - 1) ? 'visible' : 'hidden';
  }

  /* ── Zoom / Pan helpers ── */
  function resetZoom() {
    z.scale = 1; z.tx = 0; z.ty = 0;
    applyTransform();
  }

  function applyTransform() {
    imgEl.style.transform = 'translate(' + z.tx + 'px,' + z.ty + 'px) scale(' + z.scale + ')';
    imgEl.style.cursor = z.scale > 1 ? 'grab' : 'default';
  }

  function clamp() {
    var vw = window.innerWidth;
    var vh = window.innerHeight;
    var dw = imgEl.offsetWidth  || 1;
    var dh = imgEl.offsetHeight || 1;
    var maxX = Math.max(0, (dw * z.scale - vw) / 2);
    var maxY = Math.max(0, (dh * z.scale - vh) / 2);
    z.tx = Math.max(-maxX, Math.min(maxX, z.tx));
    z.ty = Math.max(-maxY, Math.min(maxY, z.ty));
  }

  function zoomAround(cx, cy, newScale) {
    var r = newScale / z.scale;
    z.tx = z.tx * r + cx * (1 - r);
    z.ty = z.ty * r + cy * (1 - r);
    z.scale = newScale;
    clamp();
    applyTransform();
  }

  /* ── Mouse wheel ── */
  function onWheel(e) {
    e.preventDefault();
    var factor   = e.deltaY > 0 ? 0.85 : 1.18;
    var newScale = Math.min(4, Math.max(1, z.scale * factor));
    if (newScale === z.scale) return;
    var rect = inner.getBoundingClientRect();
    var cx   = e.clientX - rect.left - rect.width  / 2;
    var cy   = e.clientY - rect.top  - rect.height / 2;
    zoomAround(cx, cy, newScale);
  }

  /* ── Mouse drag ── */
  function onMouseDown(e) {
    if (z.scale <= 1) return;
    z.dragging = true; z.lx = e.clientX; z.ly = e.clientY;
    imgEl.style.cursor = 'grabbing';
    e.preventDefault();
  }
  function onMouseMove(e) {
    if (!z.dragging) return;
    z.tx += e.clientX - z.lx; z.ty += e.clientY - z.ly;
    z.lx = e.clientX; z.ly = e.clientY;
    clamp(); applyTransform();
  }
  function onMouseUp() {
    if (!z.dragging) return;
    z.dragging = false;
    imgEl.style.cursor = z.scale > 1 ? 'grab' : 'default';
  }

  /* ── Touch helpers ── */
  function touchDist(t1, t2) {
    var dx = t1.clientX - t2.clientX, dy = t1.clientY - t2.clientY;
    return Math.sqrt(dx * dx + dy * dy);
  }

  function onTouchStart(e) {
    if (e.touches.length === 2) {
      e.preventDefault();
      pinch.on = true; pan1.on = false;
      pinch.d0 = touchDist(e.touches[0], e.touches[1]);
      pinch.s0 = z.scale;
      var rect = inner.getBoundingClientRect();
      pinch.mx = (e.touches[0].clientX + e.touches[1].clientX) / 2 - rect.left - rect.width  / 2;
      pinch.my = (e.touches[0].clientY + e.touches[1].clientY) / 2 - rect.top  - rect.height / 2;
    } else if (e.touches.length === 1 && z.scale > 1) {
      pan1.on = true; pinch.on = false;
      pan1.sx = e.touches[0].clientX; pan1.sy = e.touches[0].clientY;
      pan1.stx = z.tx; pan1.sty = z.ty;
    }
  }

  function onTouchMove(e) {
    if (pinch.on && e.touches.length === 2) {
      e.preventDefault();
      var d = touchDist(e.touches[0], e.touches[1]);
      var newScale = Math.min(4, Math.max(1, pinch.s0 * (d / pinch.d0)));
      zoomAround(pinch.mx, pinch.my, newScale);
    } else if (pan1.on && e.touches.length === 1 && z.scale > 1) {
      e.preventDefault();
      z.tx = pan1.stx + (e.touches[0].clientX - pan1.sx);
      z.ty = pan1.sty + (e.touches[0].clientY - pan1.sy);
      clamp(); applyTransform();
    }
  }

  function onTouchEnd(e) {
    if (e.touches.length < 2) pinch.on = false;
    if (e.touches.length === 0) pan1.on = false;
  }

  /* ── Init ── */
  function init() {
    buildDOM();
    collectGroups();
    document.addEventListener('click', function (e) {
      var a = e.target.closest('a[data-fancybox]');
      if (!a) return;
      e.preventDefault();
      collectGroups();
      var gName = a.getAttribute('data-fancybox');
      var list  = groups[gName] || [];
      var idx   = list.findIndex(function (item) { return item.el === a; });
      open(gName, idx < 0 ? 0 : idx);
    });
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', init);
  } else {
    init();
  }
})();
